    static final class OvertimeMember
    {
        private final String name;
        private final Duration elapsed;
        private final boolean paused;

        OvertimeMember(
                String name,
                Duration elapsed,
                boolean paused)
        {
            this.name = name;
            this.elapsed = elapsed;
            this.paused = paused;
        }

        String getName()
        {
            return name;
        }

        Duration getElapsed()
        {
            return elapsed;
        }

        boolean isPaused()
        {
            return paused;
        }
    }

    private static final class NearbyMemberTracker
    {
        private String displayName;
        private Instant activeSince;
        private Duration accumulatedActiveTime =
                Duration.ZERO;
        private Instant pausedAt;
        private boolean notificationSent;

        NearbyMemberTracker(
                String displayName,
                Instant activeSince)
        {
            this.displayName = displayName;
            this.activeSince = activeSince;
        }

        String getDisplayName()
        {
            return displayName;
        }

        void setDisplayName(String displayName)
        {
            this.displayName = displayName;
        }

        void pause(Instant now)
        {
            if (pausedAt != null)
            {
                return;
            }

            if (activeSince != null)
            {
                accumulatedActiveTime =
                        accumulatedActiveTime.plus(
                                Duration.between(
                                        activeSince,
                                        now
                                )
                        );
            }

            pausedAt = now;
            activeSince = null;
        }

        void resume(Instant now)
        {
            if (pausedAt == null)
            {
                return;
            }

            pausedAt = null;
            activeSince = now;
        }

        Duration getElapsed(Instant now)
        {
            if (pausedAt != null || activeSince == null)
            {
                return accumulatedActiveTime;
            }

            return accumulatedActiveTime.plus(
                    Duration.between(
                            activeSince,
                            now
                    )
            );
        }

        Duration getPausedDuration(Instant now)
        {
            if (pausedAt == null)
            {
                return Duration.ZERO;
            }

            return Duration.between(pausedAt, now);
        }

        boolean isPaused()
        {
            return pausedAt != null;
        }

        boolean markNotificationSent()
        {
            if (notificationSent)
            {
                return false;
            }

            notificationSent = true;
            return true;
        }
    }
}

