        else if (mode == RogueChestsFcConfig.PluginMode.STAFF)
        {
            contentContainer.add(createSwitchModeButton());
            contentContainer.add(
                    Box.createRigidArea(
                            new Dimension(0, 12)
                    )
            );

            if (!authorized)
            {
                contentContainer.add(createLockedPanel());
            }
            else
            {
                contentContainer.add(createPartyControlsSection());
                contentContainer.add(
                        Box.createRigidArea(
                                new Dimension(0, 8)
                        )
                );

                contentContainer.add(createStaffSyncControls());
                contentContainer.add(
                        Box.createRigidArea(
                                new Dimension(0, 14)
                        )
                );

                contentContainer.add(createBannedNamesSection());
                contentContainer.add(
                        Box.createRigidArea(
                                new Dimension(0, 14)
                        )
                );

                contentContainer.add(createCapturedNearbyNamesSection());
                contentContainer.add(
                        Box.createRigidArea(
                                new Dimension(0, 14)
                        )
                );

                contentContainer.add(createOvertimeWhitelistSection());
                contentContainer.add(
                        Box.createRigidArea(
                                new Dimension(0, 14)
                        )
                );


                contentContainer.add(createIgnoredNamesSection());
                contentContainer.add(
                        Box.createRigidArea(
                                new Dimension(0, 10)
                        )
                );

                refresh();
            }
        }
        else
        {
            contentContainer.add(createSwitchModeButton());
            contentContainer.add(
                    Box.createRigidArea(
                            new Dimension(0, 12)
                    )
            );

            contentContainer.add(createCapturedNearbyNamesSection());
            contentContainer.add(
                    Box.createRigidArea(
                            new Dimension(0, 14)
                    )
            );

            contentContainer.add(createOvertimeWhitelistSection());
            contentContainer.add(
                    Box.createRigidArea(
                            new Dimension(0, 10)
                    )
            );

            refresh();
        }

        contentContainer.revalidate();
        contentContainer.repaint();

        revalidate();
        repaint();
    }

