        );
        buttonRow.setMaximumSize(
                new Dimension(
                        Integer.MAX_VALUE,
                        BUTTON_HEIGHT
                )
        );

        buttonRow.add(leftButton);
        buttonRow.add(rightButton);

        return buttonRow;
    }

    private JButton createButton(
